from collections import deque
def fill_enclosed(grid, fill=4):
    h,w=len(grid),len(grid[0])
    bg=min(set(v for r in grid for v in r))  # background = most common? demo bg=0, line=3
    # use most common color as background
    from collections import Counter
    c=Counter(v for r in grid for v in r)
    bg=c.most_common(1)[0][0]
    seen=[[False]*w for _ in range(h)]
    q=deque()
    for i in range(h):
        for j in (0,w-1):
            if grid[i][j]==bg and not seen[i][j]: seen[i][j]=True; q.append((i,j))
    for j in range(w):
        for i in (0,h-1):
            if grid[i][j]==bg and not seen[i][j]: seen[i][j]=True; q.append((i,j))
    while q:
        i,j=q.popleft()
        for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
            ni,nj=i+di,j+dj
            if 0<=ni<h and 0<=nj<w and grid[ni][nj]==bg and not seen[ni][nj]:
                seen[ni][nj]=True; q.append((ni,nj))
    return [[fill if grid[i][j]==bg and not seen[i][j] else grid[i][j] for j in range(w)] for i in range(h)]

